INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-056-207', 'p0192', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '按魏少帝紀及孫權傳，是歲並無事，當是陳壽誤以吳嘉禾六年為赤烏五年耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-056-208', 'p0192', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '孫權為將軍，桓給事幕府，除餘姚長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-209', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權深貴待之，未及擢用，會病卒，甚見痛惜，殊其門戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-210', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權統事，辟為奏曹掾，以直道見憚，出為鬱林太守，加偏將軍，給兵二千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-211', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '父允，以輕財重士，名顯州郡，為孫權東曹掾，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-212', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權以將軍領會稽太守，統年二十，試為烏程相，民戶過萬，咸歎其惠理。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-213', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權忿公孫淵之巧詐反覆，欲親征之，瑁上疏諫曰：「臣聞聖王之御遠夷，羈縻而已，不常保有，故古者制地，謂之荒服，言慌惚無常，不可保也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-214', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權為車騎將軍，召為主簿，出為山陰令，還為參軍校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-058-215', 'p0192', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫權為將軍，遜年二十一，始仕幕府，歷東西曹令史，出為海昌屯田都尉，并領縣事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-058-216', 'p0192', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '臣松之以為遜慮孫權已退，魏得專力於己，旣能張拓形勢，使敵不敢犯，方舟順流，無復怵惕矣，何為復潛遣諸將，奄襲小縣，致令市人駭奔，自相傷害？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-058-217', 'p0192', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫權以楊笁所白遜二十事問抗，禁絕賔客，中使臨詰，抗無所顧問，事事條荅，權意漸解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-059-218', 'p0192', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '臣松之以為袁紹、劉表謂尚、琮為賢，本有傳後之意，異於孫權旣以立和而復寵霸，坐生亂階，自構家禍，方之袁、劉，昏悖甚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-060-219', 'p0192', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '孫權為車騎將軍，以柔為長史，徙桂陽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-060-220', 'p0192', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '小子吳，孫權外孫，封都鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-060-221', 'p0192', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '孫權統事，岱詣幕府，出守吳丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-060-222', 'p0192', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '評曰：山越好為叛亂，難安易動，是以孫權不遑外禦，卑詞魏氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-061-223', 'p0192', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫權殺關羽，并荊土，拜濬輔軍中郎將，授以兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-062-224', 'p0192', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '孫權承攝大業，優文徵儀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-062-225', 'p0192', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '孫策領會稽太守，綜年十四，為門下循行，留吳與孫權共讀書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-062-226', 'p0192', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '評曰：是儀、徐詳、胡綜，皆孫權之時幹興事業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-063-227', 'p0192', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '會孫權起於東南，範委身服事，每有災祥，輒推數言狀，其術多效，遂以顯名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-063-228', 'p0192', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '建安中，孫權在豫章，時有星變，以問惇，惇曰：「災在丹楊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-063-229', 'p0192', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '初孫權行師征伐，每令達有所推步，皆如其言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-064-230', 'p0192', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '恪父瑾靣長似驢，孫權大會羣臣，使人牽一驢入，長檢其靣，題曰諸葛子瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-064-231', 'p0192', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫權為車騎將軍，拜耽右司馬，以寬厚稱，早卒，無嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-064-232', 'p0192', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫權末，徙武衞都尉，為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-064-233', 'p0192', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '興少有士名，孫權時除上虞令，稍遷至尚書左曹，以五官中郎將使蜀，還為會稽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-234', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '孫權、劉備，外親內踈，羽之得意，權所不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-235', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '會孫權帥兵西過，朝議以樊、襄陽無穀，不可以禦寇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-236', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '帝曰：「孫權新破關羽，此其欲自結之時也，必不敢為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-237', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '及孫權圍江夏，遣其將諸葛瑾、張霸并攻襄陽，帝督諸軍討權，走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-238', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '初，文懿聞魏師之出也，請救於孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-002-239', 'p0192', 'jinshu', 'a05-002', '《晉書·卷二》', '」全懌母，孫權女也，得罪於吳，全端兄子禕及儀奉其母來奔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-006-240', 'p0192', 'jinshu', 'a05-006', '《晉書·卷六》', '及孫權之稱號，自謂當之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-012-241', 'p0192', 'jinshu', 'a05-012', '《晉書·卷十二》', '吳孫權赤烏十一年二月，白虹貫日，權發詔戒懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-242', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是時孫權受魏爵號，而稱兵距守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-243', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '」明年，孫權遣張彌等將兵萬人，錫授公孫文懿為燕王，文懿斬彌等，虜其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-244', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '是時，諸葛亮據渭南，宣帝與相持；孫權寇合肥，又遣陸議、孫昭等入淮沔，天子親東征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-245', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '吳孫權赤烏十三年夏五月，日北至，熒惑逆行，入南斗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-246', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '翼又楚分野，孫權封略也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-247', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '孫權發兵，緣江淮屯要衝，權自圍新城以應亮，天子東征權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-014-248', 'p0192', 'jinshu', 'a05-014', '《晉書·卷十四》', '孫權赤烏五年，亦取中州嘉號封建諸王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-015-249', 'p0192', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫權分江夏立武昌郡，又分蒼梧立臨賀郡，分長沙立衡陽、湘東二郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-015-250', 'p0192', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫權又分豫章立鄱陽郡，分丹楊立新都郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-037-251', 'p0192', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '時孫權稱藩，請送任子，當遣前將軍于禁還，久而不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-048-0', 'p0193', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫亮字子明，權少子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-048-1', 'p0193', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫亮廢，己未，孫綝使宗正孫楷與中書郎董朝迎休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-048-2', 'p0193', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '評曰：孫亮童孺而無賢輔，其替位不終，必然之勢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-050-3', 'p0193', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '得幸有娠，夢有似龍頭授己者，己以蔽膝受之，遂生孫亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-050-4', 'p0193', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫亮即位，以夫人姊壻譚紹為騎都尉，授兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-050-5', 'p0193', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫亮全夫人，全尚女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-050-6', 'p0193', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '太平中，孫亮知朱主為全主所害，問朱主死意？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-055-7', 'p0193', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫亮即位，為冠軍將軍，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-057-8', 'p0193', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '會稽典錄曰：孫亮時，有山陰朱育，少好奇字，凡所特達，依體象類，造作異字千名以上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-057-9', 'p0193', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫亮時，二子熊、損各復領兵，為全公主所譖，皆死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-059-10', 'p0193', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '基侍孫亮在內，太平二年，盜乘御馬，收付獄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-060-11', 'p0193', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '孫亮即位，遷鎮北將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-060-12', 'p0193', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '臣松之案：孫亮太平二年始立臨川郡，是時未有臨川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-064-13', 'p0193', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝以孫亮始親政事，多所難問，甚懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-065-14', 'p0193', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫亮即位，諸葛恪輔政，表曜為太史令，撰吳書，華覈、薛瑩等皆與參同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a05-013-15', 'p0193', 'jinshu', 'a05-013', '《晉書·卷十三》', '吳廢孫亮太平元年九月壬辰，太白犯南斗，吳志所書也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a05-013-16', 'p0193', 'jinshu', 'a05-013', '《晉書·卷十三》', '是歲，吳主孫亮五鳳元年也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a05-015-17', 'p0193', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫亮又分豫章立臨川郡，分會稽立臨海郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a05-034-18', 'p0193', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '祕孫亮，字長玄，有才能，多計數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-004-0', 'p0194', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '孫休遣使鄧句，勑交阯太守鎖送其民，發以為兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-004-1', 'p0194', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '又孫休病死，主帥改易，國內乖違，人各有心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-028-2', 'p0194', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '今宜厚劉禪以致孫休，安士民以來遠人，若便送禪於京都，吴以為流徙，則於向化之心不勸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-041-3', 'p0194', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '孫休怒，復遣陸抗等帥衆三萬人增憲之圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-4', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫休字子烈，權第六子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-5', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '時孫休在郡治，衡數以法繩之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-6', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫休即位，特徵偉，累遷至光祿勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-7', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫休立，封皓為烏程侯，遣就國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-8', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫休時，父亮為尚書令，而陟為中書令，每朝會，詔以屏風隔其座。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-9', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '襄陽記曰：悌字巨先，襄陽人，少有名理，孫休時為屯騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-050-10', 'p0194', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '吳主權王夫人，南陽人也，以選入宮，嘉禾中得幸，生孫休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-050-11', 'p0194', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫休朱夫人，朱據女，休姊公主所生也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-050-12', 'p0194', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫休即位，大赦，得還，以牧為五官中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-052-13', 'p0194', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」周昭者字恭遠，與韋曜、薛瑩、華覈並述吳書，後為中書郎，坐事下獄，覈表救之，孫休不聽，遂伏法云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-053-14', 'p0194', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '漢晉春秋曰：孫休時，珝為五官中郎將，遣至蜀求馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-053-15', 'p0194', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '」珝弟瑩，字道言，初為祕府中書郎，孫休即位，為散騎中常侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-055-16', 'p0194', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫休即位，與張布謀，欲誅孫綝，布曰：「丁奉雖不能吏書，而計略過人，能斷大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-057-17', 'p0194', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」歷顯位，孫休時固為左御史大夫，孫皓即位，遷司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-058-18', 'p0194', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫休時，追謚遜曰昭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-059-19', 'p0194', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫休立，封和子皓為烏程侯，自新都之本國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-059-20', 'p0194', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫休即位，封德錢唐侯，謙永安侯，俊拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-061-21', 'p0194', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫休即位，拜征北將軍，假節領豫州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-061-22', 'p0194', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '或曰寶鼎元年十二月，凱與大司馬丁奉、御史大夫丁固謀，因皓謁廟，欲廢皓立孫休子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-064-23', 'p0194', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫休曰：「盛夏出軍，士卒傷損，無尺寸之功，不可謂能；受託孤之任，死於豎子之手，不可謂智。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-065-24', 'p0194', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫休即位，與賀邵、薛瑩、虞汜俱為散騎中常侍，皆加駙馬都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-065-25', 'p0194', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫休即位，從中郎為散騎中常侍，出為吳郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-065-26', 'p0194', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫休踐阼，為中書郎、博士祭酒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a05-015-27', 'p0194', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫休分武陵立天門郡，分宜都立建平郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a05-015-28', 'p0194', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫休又分會稽立建安郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a03-013-0', 'p0195', 'houhanshu', 'a03-013', '《後漢書·卷十三》', '干寶晉記曰：「吳王孫皓將其子瑾等，泥首面縛降王濬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-004-1', 'p0195', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '孫皓諸所獻致，其皆還送，歸之于王，以恊古義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-046-2', 'p0195', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：案漢獻帝起居注云「天子從河上還，得六璽於閣上」，又太康之初孫皓送金璽六枚，無有玉，明其偽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-046-3', 'p0195', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '如其果然，以傳子孫，縱非六璽之數，要非常人所畜，孫皓之降，亦不得但送六璽，而寶藏傳國也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-046-4', 'p0195', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孫皓時，訛言謂奉當立，誅死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-5', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '己丑，封孫皓為烏程侯，皓弟德錢唐侯，謙永安侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-6', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫皓字元宗，權孫，和子也，一名彭祖，字皓宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-7', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫皓使送稷下都，稷至合浦，歐血死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-8', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」炅猶罵不止，曰：「尚欲斬汝孫皓，汝父何死狗也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-9', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '四月甲申，詔曰：「孫皓窮迫歸降，前詔待之以不死，今皓垂至，意猶愍之，其賜號為歸命侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-10', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '干寶晉紀曰：王濬治船於蜀，吳彥取其流柹以呈孫皓，曰：「晉必有攻吳之計，宜增建平兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-050-11', 'p0195', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫皓即位月餘，貶為景皇后，稱安定宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-050-12', 'p0195', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫皓滕夫人，故太常胤之族女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-052-13', 'p0195', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '條孫皓時位至尚書令、太子少傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-052-14', 'p0195', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫皓使陸抗西行，祜等遁退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-053-15', 'p0195', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '孫皓時為侍郎，以言語辯捷見知，擢為侍中、中書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-053-16', 'p0195', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '孫皓初，為左執法，遷選曹尚書，及立太子，又領少傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-053-17', 'p0195', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '干寶晉紀曰：武帝從容問瑩曰：「孫皓之所以亡者何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-055-18', 'p0195', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '休薨，奉與丞相濮陽興等從萬彧之言，共迎立孫皓，遷右大司馬左軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-057-19', 'p0195', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」歷顯位，孫休時固為左御史大夫，孫皓即位，遷司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-057-20', 'p0195', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '子喜亦涉文籍，好人倫，孫皓時為選曹尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-057-21', 'p0195', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫皓時，宣至驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-058-22', 'p0195', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫皓即位，加鎮軍大將軍，領益州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-058-23', 'p0195', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫皓聞二境交和，以詰於抗，抗曰：「夫一邑一鄉，不可以無信義之人，而況大國乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-058-24', 'p0195', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '景妻，孫皓適妹，與景俱張承外孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-25', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫皓移都，甚憚之，詔曰：「慎勳德俱茂，朕所敬憑，宜登上公，以副衆望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-26', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫皓即位，詔曰：「故僕射屈晃，志匡社稷，忠諫亡身。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-27', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫皓即位，追和、霸舊隙，削基、壹爵土，與祖母謝姬俱徙會稽烏傷縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-28', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '建衡二年，孫皓左夫人王氏卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-29', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '臣松之案：建衡二年至奮之死，孫皓即位，尚猶未乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-061-30', 'p0195', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫皓立，遷鎮西大將軍，都督巴丘，領荊州牧，進封嘉興侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-061-31', 'p0195', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫皓與晉平，使者丁忠自北還，說皓弋陽可襲，凱諫止，語在皓傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-064-32', 'p0195', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '左典軍萬彧素與烏程侯孫皓善，乃勸興、布，於是興、布廢休適子而迎立皓，皓旣踐阼，加興侍中，領青州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-33', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓初，復入為常侍，與萬彧同官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-34', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓即位，與王蕃、郭逴、萬彧俱為散騎中常侍，出為會稽太守，入為大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-35', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓時，入為左典軍，遷中書令，領太子太傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-36', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓即位，封高陵亭侯，遷中書僕射，職省，為侍中，常領左國史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-37', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓即位，封徐陵亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-002-38', 'p0195', 'jinshu', 'a05-002', '《晉書·卷二》', '冬十月丁亥，奏遣吳人相國參軍徐劭、散騎常侍水曹屬孫彧使吳，喻孫皓以平蜀之事，致馬錦等物，以示威懷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-002-39', 'p0195', 'jinshu', 'a05-002', '《晉書·卷二》', '夏四月，孫皓使紀陟來聘，且獻方物。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-40', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '三月，孫皓帥衆趨壽陽，遣大司馬望屯淮北以距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-41', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '孫皓窮蹙請降，送璽綬於琅邪王伷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-42', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '三月壬寅，王濬以舟師至于建鄴之石頭，孫皓大懼，面縳輿櫬，降于軍門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-43', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '五月辛亥，封孫皓為歸命侯，拜其太子為中郎，諸子為郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-44', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '詔選孫皓妓妾五千人入宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-006-45', 'p0195', 'jinshu', 'a05-006', '《晉書·卷六》', '故歸命侯孫皓子璠謀反，伏誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-012-46', 'p0195', 'jinshu', 'a05-012', '《晉書·卷十二》', '」是時孫皓淫暴，四月降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-013-47', 'p0195', 'jinshu', 'a05-013', '《晉書·卷十三》', '太康元年三月，大破吳軍，孫皓面縛請罪，吳國遂亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-015-48', 'p0195', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫皓分零陵立始安郡，分桂陽立始興郡，又分零陵立邵陵郡，分長沙立安成郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-015-49', 'p0195', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫皓分會稽立東陽郡，分吳立吳興郡，分豫章、廬陵、長沙立安成郡，分廬江立廬陵南部都尉，揚州統丹楊、吳、會稽、吳興、新都、東陽、臨海、建安、豫章、鄱陽、臨川、安成、廬陵南部十四郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-015-50', 'p0195', 'jinshu', 'a05-015', '《晉書·卷十五》', '及孫皓，又立新昌、武平、九德三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-51', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」孫皓聞二境交和，以詰抗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-52', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '今江淮之難，不過劍閣；山川之險，不過岷漢；孫皓之暴，侈於劉禪；吳人之困，甚於巴蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-53', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '孫皓恣情任意，與下多忌，名臣重將不復自信，是以孫秀之徒皆畏逼而至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-54', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '如舍之，若孫皓不幸而沒，吳人更立令主，雖百萬之眾，長江未可而越也，將爲後患乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-55', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '政，吳之名將也，據要害之地，恥以無備取敗，不以所喪之實告于孫皓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-56', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '若今中止，孫皓怖而生計，或徙都武昌，更完修江南諸城，遠其居人，城不可攻，野無所掠，積大船於夏口，則明年之計或無所及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-57', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '孫皓既平，振旅凱入，以功進爵當陽縣侯，增邑并前九千六百戶，封子耽爲亭侯，千戶，賜絹八千匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-037-58', 'p0195', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '孫皓率眾向壽春，詔望統中軍二萬，騎三千，據淮北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-039-59', 'p0195', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '時將發使聘吳，並遣當時文士作書與孫皓，帝用勖所作。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-040-60', 'p0195', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '使及至轘轅，而孫皓已降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-61', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '孫皓司徒何植、建威將軍孫晏送印節詣渾降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-62', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '既而王濬破石頭，降孫皓，威名益振。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-63', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '帝下詔曰：「使持節、都督揚州諸軍事、安東將軍、京陵侯王渾，督率所統，遂逼秣陵，令賊孫皓救死自衛，不得分兵上赴，以成西軍之功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-64', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '帝嘗與濟奕棋，而孫皓在側，謂皓曰：「何以好剝人面皮？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-65', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '吳建平太守吾彥取流柿以呈孫皓曰：「晉必有攻吳之計，宜增建平兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-66', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '時朝議咸諫伐吳，濬乃上疏曰：「臣數參訪吳楚同異，孫皓荒淫凶逆，荊揚賢愚無不嗟怨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-67', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '用光祿勳薛瑩、中書令胡沖計，送降文於濬曰：「吳郡孫皓叩頭死罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-68', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '彬知賊寇已殄，孫皓將降，未至建鄴二百里，稱疾遲留，以示不競。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a03-001-0', 'p0196', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '銅馬、青犢、尤來餘賊共立孫登為天子於上郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a03-001-1', 'p0196', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '春秋保乾圖曰：「賊臣起，名孫登，巧用法，多技方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a03-048-2', 'p0196', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '懿怪而問之，酺曰：「圖書有漢賊孫登，將以才智為中官所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a03-048-3', 'p0196', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '春秋保乾圖曰「漢賊臣，名孫登，大形小口，長七尺九寸，巧用法，多技方，詩書不用，賢人杜口」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-008-4', 'p0196', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」魏書曰：度語毅、儀：「讖書云孫登當為天子，太守姓公孫，字升濟，升即登也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-021-5', 'p0196', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '初，康採藥於汲郡共北山中，見隱者孫登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-021-6', 'p0196', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '康別傳云：孫登謂康曰：「君性烈而才儁，其能免乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-021-7', 'p0196', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又晉陽秋云：康見孫登，登對之長嘯，踰時不言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-059-8', 'p0196', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫登字子高，權長子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-059-9', 'p0196', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '評曰：孫登居心所存，足為茂美之德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a05-040-10', 'p0196', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '初，駿徵高士孫登，遺以布被。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-048-0', 'p0197', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '劫皓庶弟永安侯謙出烏程，取孫和陵上鼓吹曲蓋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-050-1', 'p0197', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '夫人以選入宮，黃武中得幸，生孫和，寵次步氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-050-2', 'p0197', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '及潘夫人母子有寵，全主自以與孫和母有隙，乃勸權為潘氏男亮納夫人，亮遂為嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-050-3', 'p0197', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '初，孫和為太子時，全主譖害王夫人，欲廢太子，立魯王，朱主不聽，由是有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-050-4', 'p0197', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫和何姬，丹楊句容人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-059-5', 'p0197', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '吳歷曰：孫和以無罪見殺，衆庶皆懷憤歎，前司馬桓慮因此招合將吏，欲共殺峻立英，事覺，皆見殺，英實不知。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a03-070-0', 'p0198', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '融逼急，乃遣東萊太史慈求救於平原相劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-011-1', 'p0198', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」原匿之月餘，時東萊太史慈當歸，原因以政付之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-047-2', 'p0198', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-049-3', 'p0198', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '太史慈字子義，東萊黃人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-049-4', 'p0198', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '太史慈信義篤烈，有古人之分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-051-5', 'p0198', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及軍還，郎與太史慈俱在前導軍，人以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-055-6', 'p0198', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '樂安平定，代太史慈備海昏，與周瑜為左右督，破曹公於烏林，又進攻南郡，走曹仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-056-7', 'p0198', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '又從攻祖郎於陵陽，太史慈於勇里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-009-0', 'p0199', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，楊州刺史劉繇與袁術將孫策戰于曲阿，策字伯符，孫堅子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-037-1', 'p0199', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '初平中，天下亂，避地會稽，遂浮海客交阯，東觀記曰「礹到吳郡，揚州刺史劉繇振給穀食衣服所乏者，悉不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-068-2', 'p0199', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '」遂復投揚州刺史劉繇於曲阿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-073-3', 'p0199', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '後為楊州刺史劉繇所破，走入山中，為人所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-075-4', 'p0199', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '自孫堅死，子策復領其部曲，術遣擊楊州刺史劉繇，破之，策因據江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-075-5', 'p0199', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '曹操毒被於東徐，劉表僭亂於南荊，公孫叛逆於朔北，正禮阻兵，劉繇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-001-6', 'p0199', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」兖州刺史劉岱、岱，劉繇之兄，事見吳志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-007-7', 'p0199', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '時選三署郎以補縣長；琅邪趙昱為莒長，東萊劉繇下邑長，東海王朗菑丘長，洪即丘長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-013-8', 'p0199', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '魏略曰：揚州刺史劉繇死，其衆願奉歆為主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-035-9', 'p0199', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '皓從揚州刺史劉繇求兵擊玄，玄退屯西城，皓入南昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-035-10', 'p0199', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉繇、王朗各據州郡，論安言計，動引聖人，羣疑滿腹，衆難塞胷，今歲不戰，明年不征，使孫策坐大，遂并江東，此臣之未解二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-11', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '先是，劉繇為揚州刺史，州舊治壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-12', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」術知其恨，而以劉繇據曲阿，王朗在會稽，謂策未必能定，故許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-13', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '劉繇棄軍遁逃，諸郡守皆捐城郭奔走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-14', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '劉繇旣走，策入曲阿勞賜將士，遣將陳寶詣阜陵迎母及弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-15', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '發恩布令，告諸縣：「其劉繇、笮融等故鄉部曲來降首者，一無所問；樂從軍者，一身行，復除門戶；不樂者，勿彊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-16', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '元惡旣斃，幼主東顧，俾保傅宣命，欲令諸軍振旅，然河北通謀黑山，曹操放毒東徐，劉表稱亂南荊，公孫瓚炰烋北幽，劉繇決力江滸，劉備爭盟淮隅，是以未獲承命櫜弓戢戈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-17', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '劉繇字正禮，東萊牟平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-18', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '繇奔丹徒，袁宏漢紀曰：劉繇將奔會稽，許子將曰：「會稽富實，策之所貪，且窮在海隅，不可往也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-19', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '楊州刺史劉繇與慈同郡，慈自遼東還，未與相見，暫渡江到曲阿見繇，未去，會孫策至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-20', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '後劉繇亡於豫章，士衆萬餘人未有所附，策命慈往撫安焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-21', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '今劉繇喪亡，恨不及其生時與共論辯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-22', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '評曰：劉繇藻厲名行，好尚臧否，至於擾攘之時，據萬里之土，非其長也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-050-23', 'p0199', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會景為劉繇所迫，復北依術，術以為督軍中郎將，與孫賁共討樊能、于麋於橫江，又擊笮融、薛禮於秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-050-24', 'p0199', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '從討劉繇，繇奔豫章，策遣景、賁到壽春報術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-050-25', 'p0199', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '」琨具啟策，策即行之，衆悉俱濟，遂破英，擊走笮融、劉繇，事業克定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-051-26', 'p0199', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '策破劉繇，定諸縣，進攻會稽，遣人請靜，靜將家屬與策會于錢唐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-051-27', 'p0199', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '為揚州刺史劉繇所迫逐，因將士衆還住歷陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-051-28', 'p0199', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及策東渡，助賁、景破英、能等，遂進擊劉繇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-054-29', 'p0199', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '乃渡擊秣陵，破笮融、薛禮，轉下湖孰、江乘，進入曲阿，劉繇奔走，而策之衆已數萬矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-056-30', 'p0199', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是時吳景已在丹楊，而策為術攻廬江，於是劉繇恐為袁、孫所并，遂搆嫌隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-056-31', 'p0199', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '策旣走劉繇，東定會稽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-056-32', 'p0199', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '策定秣陵、曲阿，收笮融、劉繇餘衆，增範兵二千，騎五十匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-064-33', 'p0199', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '伯父耽，父胄，與劉繇州里通家，以世擾亂，渡江依繇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a05-036-full-34', 'p0199', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '太保主簿劉繇等冒難收瓘而葬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a05-036-35', 'p0199', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '太保主簿劉繇等冒難收瓘而葬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-002-0', 'p0200', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '胡沖吳歷曰：帝以素書所著典論及詩賦餉孫權，又以紙寫一通與張昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-008-1', 'p0200', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '吳書曰：謙死時，年六十三，張昭等為之哀辭曰：「猗歟使君，君侯將軍，膺秉懿德，允武允文，體足剛直，守以溫仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-013-2', 'p0200', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '使張昭私問朗，朗誓不屈，策忿而不敢害也，留置曲阿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-038-3', 'p0200', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '孰若安時處順，端拱吳、越，與張昭、張紘之儔同保元吉者哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-039-4', 'p0200', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：輔吳將軍張昭甞對孫權論巴褊阨，不當拒張飛太甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-046-5', 'p0200', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '彭城張昭、廣陵張紘、秦松、陳端等為謀主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-046-6', 'p0200', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣松之以為張昭雖名重，然不如紘之文也，此書必紘所作。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-046-7', 'p0200', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '創甚，請張昭等謂曰：「中國方亂，夫以吳、越之衆，三江之固，足以觀成敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-8', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '策長史張昭謂權曰：「孝廉，此寧哭時邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-9', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '張昭、周瑜等謂權可與共成大業，故委心而服事焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-10', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '待張昭以師傅之禮，而周瑜、程普、呂範等為將率。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-11', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權自率衆圍合肥，使張昭攻九江之當塗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-12', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '父札，才學博達，權為驃騎將軍，以札為從事中郎，與張昭、孫邵共定朝儀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-048-13', 'p0200', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '誅叛柔服而江外厎定，飭法脩師而威德翕赫，賔禮名賢而張昭為之雄，交御豪俊而周瑜為之傑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-048-14', 'p0200', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-050-15', 'p0200', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '建安七年，臨薨，引見張昭等，屬以後事，合葬高陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-051-16', 'p0200', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '行人以告，權乃還，偽若不知，與張昭共見輔，權謂輔曰：「兄厭樂邪，何為呼他人？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-051-17', 'p0200', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '策臨卒，張昭等謂策當以兵屬儼，而策呼權，佩以印綬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-18', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '張昭字子布，彭城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-19', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '臣松之以為張昭勸迎曹公，所存豈不遠乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-20', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '習鑿齒曰：張昭於是乎不臣矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-21', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '權嘗咨問得失，張昭因陳聽采聞，頗以法令太稠，刑罰微重，宜有所蠲損。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-22', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '評曰：張昭受遺輔佐，功勳克舉，忠謇方直，動不為己；而以嚴見憚，以高見外，旣不處宰相，又不登師保，從容閭巷，養老而已，以此明權之不及策也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-23', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '表為正議校尉，吳書曰：紘與張昭並與參謀，常令一人居守，一人從征討，後呂布襲取徐州，因為之牧，不欲令紘與策從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-24', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '每有異事密計及章表書記，與四方交結，常令紘與張昭草創撰作。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-25', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '江表傳曰：初，權於羣臣多呼其字，惟呼張昭曰張公，紘曰東部，所以重二人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-26', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '張昭進之於孫權，權以為騎都尉、從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-27', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '評曰：張紘文理意正，為世令器，孫策待之亞於張昭，誠有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-28', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜將兵赴喪，遂留吳，以中護軍與長史張昭共掌衆事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-29', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權召羣臣會議，張昭、秦松等猶豫不能決，權意不欲遣質，乃獨將瑜詣母前定議，瑜曰：「昔楚國初封於荊山之側，不滿百里之地，繼嗣賢能，廣土開境，立基於郢，遂據荊揚，至於南海，傳業延祚，九百餘年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-30', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備之自京還也，權乘飛雲大船，與張昭、秦松、魯肅等十餘人共追送之，大宴會敘別。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-31', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」張昭非肅謙下不足，頗訾毀之，云肅年少麤踈，未可用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-32', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '數歲，鄧當死，張昭薦蒙代當，拜別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-33', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策薨，與張昭等共輔孫權，遂周旋三郡，平討不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-34', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策薨，權年少，初統事，太妃憂之，引見張昭及襲等，問江東可保安不，襲對曰：「江東地勢有山川之固，而討逆明府恩德在民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-35', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '討虜承基，大小用命，張昭秉衆事，襲等為爪牙，此地利人和之時也，萬無所憂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-36', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '張昭時在坐，難曰：「吳下業業，若軍果行，恐必致亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-37', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權出都亭候貞，貞有驕色，張昭旣怒，而盛忿憤，顧謂同列曰：「盛等不能奮身出命，為國家并許洛，吞巴蜀，而令吾君與貞盟，不亦辱乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-056-38', 'p0200', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '後策薨，治與張昭等共尊奉權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-056-39', 'p0200', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '後權復征江夏，範與張昭留守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-057-40', 'p0200', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權與張昭論及神仙，翻指昭曰：「彼皆死人，而語神仙，世豈有仙人也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-057-41', 'p0200', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫策在吳，張昭、張紘、秦松為上賔，共論四海未泰，須當用武治而平之，績年少末坐，遙大聲言曰：「昔管夷吾相齊桓公，九合諸侯，一匡天下，不用兵車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-057-42', 'p0200', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '罷出，張昭執其手曰：「老夫託意，君宜明之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-059-43', 'p0200', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '權欲登讀漢書，習知近代之事，以張昭有師法，重煩勞之，乃令休從昭受讀，還以授登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-062-44', 'p0200', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '遼東之事，輔吳將軍張昭以諫權言辭切至，權亦大怒，其和協彼此，使之無隙，綜有力焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-064-45', 'p0200', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '命恪行酒，至張昭前，昭先有酒色，不肯飲，曰：「此非養老之禮也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-064-46', 'p0200', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」張昭自以坐中最老，疑恪以鳥戲之，因曰：「恪欺陛下，未甞聞鳥名白頭翁者，試使恪復求白頭母。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-038-0', 'p0201', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '孰若安時處順，端拱吳、越，與張昭、張紘之儔同保元吉者哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-046-1', 'p0201', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '吳歷曰：初策在江都時，張紘有母喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-046-2', 'p0201', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '彭城張昭、廣陵張紘、秦松、陳端等為謀主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-046-3', 'p0201', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '吳錄載策使張紘為書曰：「蓋上天垂司過之星，聖王建敢諫之鼓，設非謬之備，急箴闕之言，何哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-053-4', 'p0201', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '評曰：張紘文理意正，為世令器，孫策待之亞於張昭，誠有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-057-5', 'p0201', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」會稽東部都尉張紘又與融書曰：「虞仲翔前頗為論者所侵，美寶為質，彫摩益光，不足以損。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-057-6', 'p0201', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫策在吳，張昭、張紘、秦松為上賔，共論四海未泰，須當用武治而平之，績年少末坐，遙大聲言曰：「昔管夷吾相齊桓公，九合諸侯，一匡天下，不用兵車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-057-7', 'p0201', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陳國陳融、陳留濮陽逸、沛郡蔣纂、廣陵袁迪等，皆單貧有志，就瑁游處，迪孫曄，字思光，作獻帝春秋，云迪與張紘等俱過江，迪父綏為太傅掾，張超之討董卓，以綏領廣陵事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-047-0', 'p0202', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」六月，以太常顧雍為丞相。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-047-1', 'p0202', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十一月，丞相顧雍卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-048-2', 'p0202', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-052-3', 'p0202', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '顧雍字元歎，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-052-4', 'p0202', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '自今蔽獄，都下則宜諮顧雍，武昌則陸遜、潘濬，平心專意，務在得情，隲黨神明，受罪何恨？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-052-5', 'p0202', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」又曰：「丞相顧雍、上大將軍陸遜、太常潘濬，憂深責重，志在謁誠，夙夜兢兢，寢食不寧，念欲安國利民，建乆長之計，可謂心膂股肱，社稷之臣矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-052-6', 'p0202', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '顧雍依杖素業，而將之智局，故能究極榮位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-057-7', 'p0202', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」太常顧雍曰：「基未詳其為人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-058-8', 'p0202', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '赤烏七年，代顧雍為丞相，詔曰：「朕以不德，應期踐運，王塗未一，姦宄充路，夙夜戰懼，不惶鑒寐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-061-9', 'p0202', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '時校事呂壹操弄威柄，奏桉丞相顧雍、左將軍朱據等，皆見禁止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a03-023-0', 'p0203', 'houhanshu', 'a03-023', '《後漢書·卷二十三》', '乃庸力之不暇，思鳴之無晨，吳志諸葛瑾曰「失旦之雞，復思一鳴」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-003-1', 'p0203', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '吳將諸葛瑾、張霸等寇襄陽，撫軍大將軍司馬宣王討破之，斬霸，征東大將軍曹休又破其別將於尋陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-004-2', 'p0203', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '干寶晉紀曰：吳將全琮寇芍陂，朱然、孫倫五萬人圍樊城，諸葛瑾、步隲寇柤中；琮已破走而樊圍急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-009-3', 'p0203', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '權將諸葛瑾與尚軍對江，瑾渡入江中渚，而分水軍於江中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-017-4', 'p0203', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '明帝即位，拒吳將諸葛瑾於襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-023-5', 'p0203', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時吳使朱然、諸葛瑾攻圍樊城，遣船兵於峴山東斫材，牂牁人兵作食，有先熟者呼後熟者，言：「共食來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-035-6', 'p0203', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '諸葛氏集目錄                     　　開府作牧第一　　　權制第二                     　　南征第三　　　　　北出第四                   　　計筭第五　　　　　訓厲第六                   　　綜覈上第七　　　　綜覈下第八                   　　雜言上第九　　　　雜言下第十                   　　貴和第十一　　　　兵要第十二                   　　傳運第十三　　　　與孫權書第十四                   　　與諸葛瑾書第十五　與孟達書第十六                   　　廢李平第十七　　　法檢上第十八                   　　法檢下第十九　　　科令上第二十                   　　科令下第二十一　　軍令上第二十二                   　　軍令中第二十三　　軍令下第二十四                   　右二十四篇，凡十萬四千一百一十二字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-7', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '招延俊秀，聘求名士，魯肅、諸葛瑾等始為賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-8', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權以備已得益州，令諸葛瑾從求荊州諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-9', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權令諸葛瑾報，更尋盟好，遂分荊州長沙、江夏、桂陽以東屬權，南郡、零陵、武陵以西屬備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-10', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權遣呂範等督五軍，以舟軍拒休等，諸葛瑾、潘璋、楊粲救南郡，朱桓以濡須督拒仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-11', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」於是令有司盡寫科條，使郎中褚逢齎以就遜及諸葛瑾，意所不安，令損益之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-12', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」夏五月，權遣陸遜、諸葛瑾等屯江夏、沔口，孫韶、張承等向廣陵、淮陽，權率大衆圍合肥新城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-13', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '禮還，復有詔責數諸葛瑾、步隲、朱然、呂岱等曰：「袁禮還，云與子瑜、子山、義封、定公相見，並以時事當有所先後，各自以不掌民事，不肯便有所陳，悉推之伯言、承明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-14', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '車騎將軍朱然圍樊，大將軍諸葛瑾取柤中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-15', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陛下身自御戎，取亂侮亡，宜滌荊、揚之地，舉彊羸之數，使彊者執戟，羸者轉運，西命益州軍于隴右，授諸葛瑾、朱然大衆指事襄陽，陸遜、朱桓別征壽春，大駕入淮陽，歷青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-16', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '及權繼其業，有張子布以為腹心，有陸議、諸葛瑾、步隲以為股肱，有呂範、朱然以為爪牙，分任受職，乘閒伺隙，兵不妄動，故戰少敗而江南安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-048-17', 'p0203', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-051-18', 'p0203', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '輕財能施，善於交結，與諸葛瑾至厚，委廬江劉靖以得失，江夏李允以衆事，廣陵吳碩、河南張梁以軍旅，而傾心親待，莫不自盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-19', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '承字仲嗣，少以才學知名，與諸葛瑾、步隲、嚴畯相友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-20', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '初，承喪妻，昭欲為索諸葛瑾女，承以相與有好，難之，權聞而勸焉，遂為婚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-21', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '臣松之案：承與諸葛瑾同以赤烏中卒，計承年小瑾四歲耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-22', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '諸葛瑾字子瑜，琅邪陽都人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-23', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權為討虜將軍，召隲為主記，吳書曰：歲餘，隲以疾免，與琅邪諸葛瑾、彭城嚴畯俱游吳中，並著聲名，為當時英俊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-24', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-25', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '諸葛瑾、步隲並以德度規檢見器當世，張承、顧邵虛心長者，好尚人物，周昭之論，稱之甚美，故辭錄焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-053-26', 'p0203', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '避亂江東，與諸葛瑾、步隲齊名友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-054-27', 'p0203', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '赤烏二年，諸葛瑾、步隲連名上疏曰：「故將軍周瑜子胤，昔蒙粉飾，受封為將，不能養之以福，思立功效，至縱情欲，招速罪辟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-055-28', 'p0203', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏將夏侯尚等圍南郡，分前部三萬人作浮橋，渡百里洲上，諸葛瑾、楊粲並會兵赴救，未知所出，而魏兵日渡不絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-056-29', 'p0203', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '諸葛瑾子融、步隲子恊，雖各襲任，權特復使然總為大督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-058-30', 'p0203', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '嘉禾五年，權北征，使遜與諸葛瑾攻襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-059-31', 'p0203', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-060-32', 'p0203', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a05-001-33', 'p0203', 'jinshu', 'a05-001', '《晉書·卷一》', '及孫權圍江夏，遣其將諸葛瑾、張霸并攻襄陽，帝督諸軍討權，走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a05-001-34', 'p0203', 'jinshu', 'a05-001', '《晉書·卷一》', '二年夏五月，吳將全琮寇芍陂，朱然、孫倫圍樊城，諸葛瑾、步騭掠柤中，帝請自討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0204-a05-001-0', 'p0204', 'jinshu', 'a05-001', '《晉書·卷一》', '二年夏五月，吳將全琮寇芍陂，朱然、孫倫圍樊城，諸葛瑾、步騭掠柤中，帝請自討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-0', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '權嘗問衞尉嚴畯：「寧念小時所闇書不」？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-1', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昭曰：「嚴畯鄙生，臣請為陛下誦之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-2', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '承字仲嗣，少以才學知名，與諸葛瑾、步隲、嚴畯相友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-3', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權為討虜將軍，召隲為主記，吳書曰：歲餘，隲以疾免，與琅邪諸葛瑾、彭城嚴畯俱游吳中，並著聲名，為當時英俊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-4', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '潁川周昭著書稱步隲及嚴畯等曰：「古今賢士大夫所以失名喪身傾家害國者，其由非一也，然要其大歸，總其常患，四者而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-053-5', 'p0205', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '嚴畯字曼才，彭城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-053-6', 'p0205', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '嚴畯薦崇行足以厲俗，學足以為師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-056-7', 'p0205', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '江表傳曰：初，權移都建業，大會將相文武，時謂嚴畯曰：「孤昔歎魯子敬比鄧禹，呂子衡方吳漢，閒卿諸人未平此論，今定云何？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-059-8', 'p0205', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0206-a04-053-0', 'p0206', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '程秉字德樞，汝南南頓人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-053-0', 'p0207', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '闞澤字德潤，會稽山陰人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-053-1', 'p0207', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '西使張奉於權前列尚書闞澤姓名以嘲澤，澤不能荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-057-2', 'p0207', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '固在襁褓中，闞澤見而異之，曰：「此兒後必致公輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-057-3', 'p0207', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '其淵懿純德，則太子少傅山陰闞澤，學通行茂，作帝師儒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-059-4', 'p0207', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-059-5', 'p0207', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '少以母王有寵見愛，年十四，為置宮衞，使中書令闞澤教以書藝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-059-6', 'p0207', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '闞澤為太傅，薛綜為少傅，而蔡穎、張純、封俌、嚴維等皆從容侍從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-063-7', 'p0207', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '達寶惜其術，自闞澤、殷禮皆名儒善士，親屈節就學，達祕而不告。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a05-017-8', 'p0207', 'jinshu', 'a05-017', '《晉書·卷十七》', '吳中書令闞澤受劉洪乾象法於東萊徐岳，又加解注。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-007-0', 'p0208', 'houhanshu', 'a03-007', '《後漢書·卷七》', '飾芳林而考濯龍之宮，薛綜注東京賦云：「濯龍，殿名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-040-1', 'p0208', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '薛綜注西京賦曰：「颯纚，長袖貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-094-2', 'p0208', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '薛綜曰：「九賔謂王、侯、公、卿、二千石、六百石下及郎、吏、匈奴侍子，凡九等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-094-3', 'p0208', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」薛綜注二京賦曰：「為天神借民力於此田，故名曰帝藉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-095-4', 'p0208', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」薛綜曰：「侲之言善，善童幼子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-098-5', 'p0208', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」薛綜注曰：「八達謂室有八䆫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-098-6', 'p0208', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」薛綜注曰：「於上班敎曰明堂，大合樂射饗者辟雍，司曆記候節氣者曰靈臺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-7', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」薛綜曰：「樹翠羽為蓋，如雲龍矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-8', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」薛綜曰：「釳中央低，兩頭高，如山形，而貫中翟尾結著之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-9', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」薛綜曰：「戈，句孑戟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-10', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」薛綜曰：「耜，耒金也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-11', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '屬車八十一乘，薛綜曰：「屬之言相連屬也，皆在後，為三行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-12', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鳳皇闟戟，薛綜曰：「闟之言函也，取四戟函車邊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-13', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '薛綜曰：「侍御史載之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-14', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '薛綜曰：「飛軨，以緹油廣八寸，長注地，畫左蒼龍右白虎，繫軸頭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-120-15', 'p0208', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」薛綜曰：「以珩玉為充耳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-120-16', 'p0208', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」薛綜曰：「下輪大，上輪小。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-047-17', 'p0208', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」尚書僕射薛綜等切諫乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-052-18', 'p0208', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '薛綜為選曹尚書，固讓譚曰：「譚心精體密，貫道達微，才照人物，德允衆望，誠非愚臣所可越先。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-053-19', 'p0208', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '薛綜字敬文，沛郡竹邑人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-053-20', 'p0208', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '薛綜學識規納，為吳良臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-059-21', 'p0208', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '闞澤為太傅，薛綜為少傅，而蔡穎、張純、封俌、嚴維等皆從容侍從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-061-22', 'p0208', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '先帝外仗顧、陸、朱、張，內近胡綜、薛綜，是以庶績雍熈，邦內清肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-064-23', 'p0208', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '權嘉其功，遣尚書僕射薛綜勞軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a03-009-0', 'p0209', 'houhanshu', 'a03-009', '《後漢書·卷九》', '曹操以舟師伐孫權，權將周瑜敗之於烏林、赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-009-1', 'p0209', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '從平荊州，以仁行征南將軍，留屯江陵，拒吳將周瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-017-2', 'p0209', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又與滿寵討關羽於漢津，與曹仁擊周瑜於江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-018-3', 'p0209', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉備與周瑜圍曹仁於江陵，別遣關羽絕北道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-032-4', 'p0209', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '權遣周瑜、程普等水軍數萬與先主并力，江表傳曰：備從魯肅計，進住鄂縣之樊口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-032-5', 'p0209', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '江表傳曰：周瑜為南郡太守，分南岸地以給備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-035-6', 'p0209', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」權大恱，即遣周瑜、程普、魯肅等水軍三萬，隨亮詣先主，并力拒曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-037-7', 'p0209', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '吳將周瑜助先主取荊州，因領南郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-037-8', 'p0209', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」備歎息曰：「孤時危急，當有所求，故不得不往，殆不免周瑜之手！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-046-9', 'p0209', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '堅初興義兵，策將母徙居舒，與周瑜相友，收合士大夫，江、淮間人咸向之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-046-10', 'p0209', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '有周瑜者，與策同年，亦英達夙成，聞策聲聞，自舒來造焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-046-11', 'p0209', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時策西討黃祖，行及石城，聞勳輕身詣海昏，便分遣從兄賁、輔率八千人於彭澤待勳，自與周瑜率二萬人步襲皖城，即克之，得術百工及鼓吹部曲三萬餘人，并術、勳妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-046-12', 'p0209', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-047-13', 'p0209', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '張昭、周瑜等謂權可與共成大業，故委心而服事焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-047-14', 'p0209', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '待張昭以師傅之禮，而周瑜、程普、呂範等為將率。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-047-15', 'p0209', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備進住夏口，使諸葛亮詣權，權遣周瑜、程普等行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-048-16', 'p0209', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '誅叛柔服而江外厎定，飭法脩師而威德翕赫，賔禮名賢而張昭為之雄，交御豪俊而周瑜為之傑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-048-17', 'p0209', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-048-18', 'p0209', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '而周瑜驅我偏師，黜之赤壁，喪旗亂轍，僅而獲免，收迹遠遁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-048-19', 'p0209', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '執鞭鞠躬，以重陸公之威；悉委武衞，以濟周瑜之師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-050-20', 'p0209', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '生二女，長曰魯班，字大虎，前配周瑜子循，後配全琮；少曰魯育，字小虎，前配朱據，後配劉纂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-051-21', 'p0209', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '十一年，與周瑜共討麻、保二屯，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-051-22', 'p0209', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '昔周瑜、程普為左右部督，共攻江陵，雖事決於瑜，普自恃乆將，且俱是督，遂共不睦，幾敗國事，此目前之戒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-051-23', 'p0209', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '周瑜到巴丘，輔遂得進據廬陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-052-24', 'p0209', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '江表傳曰：權旣即尊位，請會百官，歸功周瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-052-25', 'p0209', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昭忠謇亮直，有大臣節，權敬重之，然所以不相昭者，蓋以昔駮周瑜、魯肅等議為非也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-053-26', 'p0209', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '黃武四年，權為太子登娉周瑜女，秉守太常，迎妃於吳，權親幸秉船，深見優禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-27', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜字公瑾，廬江舒人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-28', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '于時周瑜使鄱陽，肅勸權呼瑜，瑜使鄱陽還，但與肅闇同，故能共成大勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-29', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '東方將吏，無有愚智，皆知其不可，惟周瑜、魯肅偏懷淺戇，意未解耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-30', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後著令曰：「故將軍周瑜、程普，其有人客，皆不得問。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-31', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」後書與權曰：「赤壁之役，值有疾病，孤燒船自退，橫使周瑜虛獲此名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-32', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '赤烏二年，諸葛瑾、步隲連名上疏曰：「故將軍周瑜子胤，昔蒙粉飾，受封為將，不能養之以福，思立功效，至縱情欲，招速罪辟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-33', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜為居巢長，將數百人故過候肅，并求資糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-34', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '肅家有兩囷米，各三千斛，肅乃指一囷與周瑜，瑜益知其奇也，遂相親結，定僑、札之分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-35', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」權然之，乃遣周瑜助備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-36', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時周瑜受使至鄱陽，肅勸追召瑜還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-37', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜病困，上疏曰：「當今天下，方有事役，是瑜乃心夙夜所憂，願至尊先慮未然，然後康樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-38', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '先是，益州牧劉璋綱維頹弛，周瑜、甘寧並勸權取蜀，權以咨備，備內欲自規，乃偽報曰：「備與璋託為宗室，兾憑英靈，以匡漢朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-39', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是歲，又與周瑜、程普等西破曹公於烏林，圍曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-40', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅代周瑜，當之陸口，過蒙屯下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-41', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後魯肅上代周瑜，過蒙言議，常欲受屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-42', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權與陸遜論周瑜、魯肅及蒙曰：「公瑾雄烈，膽略兼人，遂破孟德，開拓荊州，邈焉難繼，君今繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-43', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜、魯肅建獨斷之明，出衆人之表，實奇才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-44', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '樂安平定，代太史慈備海昏，與周瑜為左右督，破曹公於烏林，又進攻南郡，走曹仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-45', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周瑜卒，代領南郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-46', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '建安中，隨周瑜拒曹公於赤壁，建策火攻，語在瑜傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-47', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後以中郎將與周瑜等拒破曹公，又與呂蒙襲取南郡，遷偏將軍，領永昌太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-48', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後與周瑜、程普拒曹公於赤壁，攻曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-49', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周瑜、呂蒙皆共薦達，孫權加異，同於舊臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-50', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後隨周瑜拒破曹公於烏林。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-51', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權以統為承烈都尉，與周瑜等拒破曹公於烏林，遂攻曹仁，遷為校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-056-52', 'p0209', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹公至赤壁，與周瑜等俱拒破之，拜裨將軍，領彭澤太守，以彭澤、柴桑、歷陽為奉邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-032-0', 'p0210', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣諸葛亮自結於孫權，江表傳曰：孫權遣魯肅弔劉表二子，并令與備相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-032-1', 'p0210', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '權遣周瑜、程普等水軍數萬與先主并力，江表傳曰：備從魯肅計，進住鄂縣之樊口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-032-2', 'p0210', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備欲呼魯肅等共會語，瑜曰：「受命不得妄委署，若欲見子敬，可別過之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-035-3', 'p0210', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」權大恱，即遣周瑜、程普、魯肅等水軍三萬，隨亮詣先主，并力拒曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-037-4', 'p0210', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '吳將魯肅遺先主書曰：「龐士元非百里才也，使處治中、別駕之任，始當展其驥足耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-5', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '招延俊秀，聘求名士，魯肅、諸葛瑾等始為賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-6', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '荊州牧劉表死，魯肅乞奉命弔表二子，且以觀變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-7', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十五年，分豫章為鄱陽郡；分長沙為漢昌郡，以魯肅為太守，屯陸口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-8', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權大怒，乃遣呂蒙督鮮于丹、徐忠、孫規等兵二萬取長沙、零陵、桂陽三郡，使魯肅以萬人屯巴丘巴丘今曰巴陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-9', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '蒙使人誘普，普降，盡得三郡將守，因引軍還，與孫皎、潘璋并魯肅兵並進，拒羽於益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-10', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」帝問其狀，咨曰：「納魯肅於凡品，是其聦也；拔呂蒙於行陣，是其明也；獲于禁而不害，是其仁也；取荊州而兵不血刃，是其智也；據三州虎視於天下，是其雄也；屈身於陛下，是其略也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-048-11', 'p0210', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-048-12', 'p0210', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '故魯肅一面而自託，士燮蒙險而效命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-048-13', 'p0210', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '高張公之德而省游田之娛，賢諸葛之言而割情欲之歡，感陸公之規而除刑政之煩，奇劉基之議而作三爵之誓，屏氣跼蹐以伺子明之疾，分滋損甘以育淩統之孤，登壇慷慨歸魯肅之功，削投惡言信子瑜之節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-052-14', 'p0210', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昭忠謇亮直，有大臣節，權敬重之，然所以不相昭者，蓋以昔駮周瑜、魯肅等議為非也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-052-15', 'p0210', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '值孫策卒，孫權姊壻曲阿弘咨見而異之，薦之於權，與魯肅等並見賔待，後為權長史，轉中司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-053-16', 'p0210', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '及橫江將軍魯肅卒，權以畯代肅，督兵萬人，鎮據陸口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-17', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」　臣松之以為建計拒曹公，實始魯肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-18', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時劉備為曹公所破，欲引南渡江，與魯肅遇於當陽，遂共圖計，因進住夏口，遣諸葛亮詣權，權遂遣瑜及程普等與備并力逆曹公，遇於赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-19', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '東方將吏，無有愚智，皆知其不可，惟周瑜、魯肅偏懷淺戇，意未解耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-20', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備之自京還也，權乘飛雲大船，與張昭、秦松、魯肅等十餘人共追送之，大宴會敘別。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-21', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅字子敬，臨淮東城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-22', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」魏書及九州春秋曰：曹公征荊州，孫權大懼，魯肅實欲勸權拒曹公，乃激說權曰：「彼曹公者，實嚴敵也，新并袁紹，兵馬甚精，乘戰勝之威，伐喪亂之國，克可必也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-23', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫盛曰：吳書及江表傳，魯肅一見孫權便說拒曹公而論帝王之略，劉表之死也，又請使觀變，無緣方復激說勸迎曹公也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-24', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅智略足任，乞以代瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-25', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅忠烈，臨事不苟，可以代瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-26', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅代周瑜，當之陸口，過蒙屯下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-27', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後魯肅上代周瑜，過蒙言議，常欲受屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-28', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權時住陸口，使魯肅將萬人屯益陽拒羽，而飛書召蒙，使捨零陵，急還助肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-29', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅卒，蒙西屯陸口，肅軍人馬萬餘盡以屬蒙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-30', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，魯肅等以為曹公尚存，禍難始搆，宜相輔協，與之同仇，不可失也，蒙乃密陳計策曰：「令征虜守南郡，潘璋住白帝，蔣欽將游兵萬人，循江上下，應敵所在，蒙為國家前據襄陽，如此，何憂於操，何賴於羽？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-31', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權與陸遜論周瑜、魯肅及蒙曰：「公瑾雄烈，膽略兼人，遂破孟德，開拓荊州，邈焉難繼，君今繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-32', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜、魯肅建獨斷之明，出衆人之表，實奇才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-055-33', 'p0210', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後隨魯肅鎮益陽，拒關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-060-34', 'p0210', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '權遣橫江將軍魯肅攻攸，碭得突走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-061-35', 'p0210', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '右國史華覈表薦禕曰：「禕體質方剛，器幹彊固，董率之才，魯肅不過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-032-0', 'p0211', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」權忿之，乃遣呂蒙襲奪長沙、零陵、桂陽三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-036-1', 'p0211', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '按呂蒙傳云：「伏精兵於𦩷𦪇之中，使白衣搖櫓，作商賈服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-040-2', 'p0211', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '」建安二十年，權遣呂蒙奄襲南三郡，立脫身走，自歸先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-045-3', 'p0211', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '為吳將呂蒙所譎，開城詣蒙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-4', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-5', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十三年春，權復征黃祖，祖先遣舟兵拒軍，都尉呂蒙破其前鋒，而淩統、董襲等盡銳攻之，遂屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-6', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '時甘寧在夷陵，為仁黨所圍，用呂蒙計，留凌統以拒仁，以其半救寧，軍以勝反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-7', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權大怒，乃遣呂蒙督鮮于丹、徐忠、孫規等兵二萬取長沙、零陵、桂陽三郡，使魯肅以萬人屯巴丘巴丘今曰巴陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-8', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '閏月，權征羽，先遣呂蒙襲公安，獲將軍士仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-9', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」帝問其狀，咨曰：「納魯肅於凡品，是其聦也；拔呂蒙於行陣，是其明也；獲于禁而不害，是其仁也；取荊州而兵不血刃，是其智也；據三州虎視於天下，是其雄也；屈身於陛下，是其略也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-048-10', 'p0211', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-048-11', 'p0211', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '拔呂蒙於戎行，識潘濬於係虜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-051-12', 'p0211', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '近聞卿與甘興霸飲，因酒發作，侵陵其人，其人求屬呂蒙督中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-051-13', 'p0211', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '後呂蒙當襲南郡，權欲令皎與蒙為左右部大督，蒙說權曰：「若至尊以征虜能，宜用之；以蒙能，宜用蒙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-052-14', 'p0211', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後從討關羽，封宣城侯，以綏南將軍代呂蒙領南郡太守，住公安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-15', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜用呂蒙計，留凌統以守其後，身與蒙上救寧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-16', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '備旣定益州，權求長沙、零、桂，備不承旨，權遣呂蒙率衆進取。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-17', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '呂蒙字子明，汝南富陂人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-18', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權常歎曰：「人長而進益，如呂蒙、蔣欽，蓋不可及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-19', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」呂蒙曰：「兵有利鈍，戰無百勝，如有邂逅，敵步騎蹙人，不暇及水，其得入船乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-20', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '以蒙為南郡太守，封孱陵侯，江表傳曰：權於公安大會，呂蒙以疾辭，權笑曰：「禽羽之功，子明謀也，今大功已捷，慶賞未行，豈邑邑邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-21', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '呂蒙勇而有謀斷，識軍計，譎郝普，禽關羽，最其妙者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-22', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後以中郎將與周瑜等拒破曹公，又與呂蒙襲取南郡，遷偏將軍，領永昌太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-23', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹公出濡須，欽與呂蒙持諸軍節度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-24', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周瑜、呂蒙皆共薦達，孫權加異，同於舊臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-25', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '遣使報瑜，瑜用呂蒙計，帥諸將解圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-26', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '建安二十年，從攻合肥，會疫疾，軍旅皆已引出，唯車下虎士千餘人，并呂蒙、蔣欽、凌統及寧，從權逍遙津北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-27', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '甞於呂蒙舍會，酒酣，統乃以刀舞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-28', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '寧厨下兒曾有過，走投呂蒙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-29', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時呂蒙敗其水軍，而統先搏其城，於是大獲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-30', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '與呂蒙等西取三郡，反自益陽，從往合肥，為右部督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-31', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫盛曰：觀孫權之養士也，傾心竭思，以求其死力，泣周泰之夷，殉陳武之妾，請呂蒙之命，育凌統之孤，卑曲苦志，如此之勤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-056-32', 'p0211', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '虎威將軍呂蒙病篤，權問曰：「卿如不起，誰可代者？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-056-33', 'p0211', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '自創業功臣疾病，權意之所鍾，呂蒙、凌統最重，然其次矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-057-34', 'p0211', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '呂蒙圖取關羽，稱疾還建業，以翻兼知醫術，請以自隨，亦欲因此令翻得釋也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-057-35', 'p0211', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權咨嗟將率，發憤歎息，追思呂蒙、張溫，以為據才兼文武，可以繼之，自是拜建義校尉，領兵屯湖孰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-058-36', 'p0211', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '呂蒙稱疾詣建業，遜往見之，謂曰：「關羽接境，如何遠下，後不當可憂也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-058-37', 'p0211', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '權乃潛軍而上，使遜與呂蒙為前部，至即克公安、南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-060-38', 'p0211', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '建安二十四年，劉備將關羽圍樊、襄陽，琮上疏陳羽可討之計，權時已與呂蒙陰議襲之，恐事泄，故寢琮表不荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-062-39', 'p0211', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '呂蒙圖襲關羽，權以問儀，儀善其計，勸權聽之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-063-40', 'p0211', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '權與呂蒙謀襲關羽，議之近臣，多曰不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a05-001-41', 'p0211', 'jinshu', 'a05-001', '《晉書·卷一》', '權果遣將呂蒙西襲公安，拔之，羽遂為蒙所獲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-032-0', 'p0212', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '權遣周瑜、程普等水軍數萬與先主并力，江表傳曰：備從魯肅計，進住鄂縣之樊口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-035-1', 'p0212', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」權大恱，即遣周瑜、程普、魯肅等水軍三萬，隨亮詣先主，并力拒曹公。');
